class WordDictionary:
    def __init__(self):
        self.root = TrieNode()

    def add_word(self, word):
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word):
        def dfs(node, i):
            if i == len(word):
                return node.is_end
            ch = word[i]
            if ch == ".":
                return any(dfs(child, i + 1) for child in node.children.values())
            if ch not in node.children:
                return False
            return dfs(node.children[ch], i + 1)
        return dfs(self.root, 0)

def find_circle_num(is_connected):
    n = len(is_connected)
    seen = set()

    def visit(i):
        seen.add(i)
        for j in range(n):
            if is_connected[i][j] and j not in seen:
                visit(j)

    provinces = 0
    for i in range(n):
        if i not in seen:
            provinces += 1               # a new, unvisited city starts a new group
            visit(i)                     # mark everything connected to it
    return provinces

def can_finish(num_courses, prerequisites):
    graph = {i: [] for i in range(num_courses)}
    for course, pre in prerequisites:
        graph[course].append(pre)

    state = {}                      # 0 = on the current path, 1 = fully explored

    def has_cycle(node):
        if state.get(node) == 0:
            return True             # back edge: we looped onto our own path
        if state.get(node) == 1:
            return False            # already proven safe
        state[node] = 0
        for pre in graph[node]:
            if has_cycle(pre):
                return True
        state[node] = 1
        return False

    return not any(has_cycle(c) for c in range(num_courses))

