def alien_order(words):
    graph = {c: set() for w in words for c in w}
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                graph[x].add(y)              # x comes before y
                break
        else:
            if len(a) > len(b):
                return ""                    # "abc" cannot come before "ab"
    indegree = {c: 0 for c in graph}
    for c in graph:
        for nxt in graph[c]:
            indegree[nxt] += 1
    queue = deque(c for c in indegree if indegree[c] == 0)
    out = []
    while queue:
        c = queue.popleft()
        out.append(c)
        for nxt in graph[c]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)
    return "".join(out) if len(out) == len(graph) else ""

